// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Set MinSum to 5
        c.SetMinSum(5);
        // Step 2: Initialize (sets intitalized = true)
        c.Initialized();
        // Step 3: Try to set MinSum again to 10; must catch revert
        // Reference reverts because intitalized is true, so MinSum remains 5
        // Bug does NOT revert because condition is !intitalized (false), so MinSum becomes 10
        bool ok;
        try c.SetMinSum(10) {
            ok = true;
        } catch {
            ok = false;
        }
        // Expected: reference reverts (ok == false) so MinSum is 5
        // Bug: ok == true so MinSum becomes 10
        // Assert that MinSum == 5 (this holds in reference, fails in bug)
        assertEq(c.MinSum(), 5);
    }
}

