import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy and set up state
        // Call SetMinSum first
        c.SetMinSum(100);
        // Call Initialized to set intitalized to true
        c.Initialized();
        // Now attempt to call SetMinSum again
        bool ok;
        try c.SetMinSum(200) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference version: fails (reverts) because intitalized is true
        // Bug version: succeeds because guard is if(!intitalized)revert();
        assertTrue(!ok);
    }
}

