pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up scenario: deployer calls SetMinSum with 1 ether, then initializes
        // Then user deposits 2 ether with any lock time, then tries to collect 1 ether after lock expires
        // In the reference, MinSum = 1 ether, so Collect succeeds only if balance >= 1 ether and balance >= _am and time > unlockTime
        // In the bug, MinSum = 0 always, so Collect condition is easier to satisfy
        // We'll check that after the deposit and warp, Collect fails in the reference (MinSum is high) because we expect revert
        // But in the bug it would succeed. However we need an assertion that passes in reference and fails in bug.
        // Better: check that after SetMinSum(1 ether), MinSum is 1 ether in reference, but 0 in bug.
        c.SetMinSum(1 ether);
        c.SetLogFile(address(0xdead));
        c.Initialized();
        // Now act as user
        address user = address(0x1234);
        vm.deal(user, 5 ether);
        vm.prank(user);
        c.Put{value: 2 ether}(1); // lock for 1 second
        vm.warp(block.timestamp + 2); // unlock
        // Now user tries to collect 1 ether
        // In reference: MinSum = 1 ether, user balance = 2 ether, time > unlockTime -> Collect should succeed
        // In bug: MinSum = 0, also succeed. So not divergent.
        // Need different: Let's set MinSum to a value that is large enough that Collect should fail in reference, but in bug fails because of MinSum=0 condition? Actually bug has MinSum=0 so it's easier to succeed, not fail.
        // To make assertion fail in bug, we need reference to succeed but bug to fail, or vice versa.
        // Since bug always sets MinSum=0, any Collect requiring MinSum>0 will succeed in bug but may fail in reference if MinSum set high.
        // So pick scenario where reference MinSum is large enough to block Collect, but bug MinSum=0 allows Collect.
        // Then after Collect, user balance differs. We'll check final balance.
        // Let's redo:
        // Deploy, call SetMinSum(10 ether) in reference, then initialize.
        // User deposits 5 ether with lock 0, then tries to collect 3 ether after warp.
        // Reference: MinSum=10 ether, user balance=5, condition acc.balance>=MinSum fails -> Collect does nothing (no Ether sent).
        // Bug: MinSum=0, condition passes -> Collect sends 3 ether.
        // So after Collect, reference user balance (in contract) remains 5 ether, bug user balance becomes 2 ether.
        // Assert: after Collect attempt, user's balance (via Acc getter) is 5 ether in reference, but bug would have 2 ether.
        // That is observable divergence.
        // But note: Collect may revert if external call fails? No, it uses call with empty data, user is a contract? No, user is address.
        // We'll use address(0x1234) not a contract, so call succeeds.

        // Reinitialize for clean state:
        delete c; // can't delete, just redeploy in setUp before each test? The test runs once, but we can just write sequence.
        // Actually setUp deploys once. We'll call functions.
        // But we need to reset? No, we are writing one test that calls functions sequentially.
        // However we already called SetMinSum earlier. Let's start from scratch: The test is deployed fresh per test, so setUp gives clean contract.
        // So just call functions in order.
        c.SetMinSum(10 ether);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // deposit
        vm.deal(user, 5 ether);
        vm.prank(user);
        c.Put{value: 5 ether}(0); // no lock
        vm.warp(block.timestamp + 1); // just in case

        // try collect 3 ether
        vm.prank(user);
        c.Collect(3 ether);

        // Now check: in reference, Collect did nothing because MinSum=10 ether > balance=5, so balance unchanged (5 ether)
        // In bug, Collect succeeds because MinSum=0, sending 3 ether, balance becomes 2 ether
        // So assertion: c.Acc(user).balance == 5 ether
        // But note: function Collect does not revert, it just does nothing if condition fails, so no revert.
        (uint unlockTime, uint balance) = c.Acc(user);
        assertEq(balance, 5 ether);
    }
}

