// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 0 and initialize the contract
        c.SetMinSum(0);
        c.Initialized();

        // User sends 1 wei (calls Put(0) via fallback, setting unlockTime)
        vm.deal(address(0x123), 1 ether);
        vm.prank(address(0x123));
        (bool ok1,) = address(c).call{value: 1}('');
        assertTrue(ok1);

        // Now warp to after unlockTime (block.timestamp increased by 1)
        vm.warp(block.timestamp + 2);

        // User tries to collect 1 wei
        vm.prank(address(0x123));
        (bool ok2,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 1));
        assertTrue(ok2);

        // After successful collect, user's balance should be 0
        uint256 bal = c.Acc(address(0x123)).balance;
        assertEq(bal, 0);
    }
